def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            positions = {}
            for y, x in component:
                positions.setdefault(grid[y][x], []).append((y, x))

            colors = list(positions)
            colors.sort(key=lambda color: (
                (max(y for y, x in positions[color]) - min(y for y, x in positions[color]) + 1)
                * (max(x for y, x in positions[color]) - min(x for y, x in positions[color]) + 1)
            ), reverse=True)

            for source, target in zip(colors, reversed(colors)):
                for y, x in positions[source]:
                    out[y][x] = target

    return out
